import{_ as a,o as e,c as s,a6 as t}from"./chunks/framework.BrkgobfX.js";const u=JSON.parse('{"title":"范围请求","description":"Range 的三种范围形式、Content-Range 语法、206 与 multipart/byteranges 的构造。","frontmatter":{"title":"范围请求","description":"Range 的三种范围形式、Content-Range 语法、206 与 multipart/byteranges 的构造。","source":"https://daiw.org/manual/http11/range-requests"},"headers":[],"relativePath":"manual/computer-programming/http11/range-requests.md","filePath":"manual/computer-programming/http11/range-requests.md"}'),p={name:"manual/computer-programming/http11/range-requests.md"};function l(i,n,r,o,c,d){return e(),s("div",null,[...n[0]||(n[0]=[t(`<h1 id="范围请求" tabindex="-1">范围请求 <a class="header-anchor" href="#范围请求" aria-label="Permalink to &quot;范围请求&quot;">​</a></h1><h2 id="accept-ranges" tabindex="-1">Accept-Ranges <a class="header-anchor" href="#accept-ranges" aria-label="Permalink to &quot;Accept-Ranges&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Accept-Ranges = acceptable-ranges</span></span>
<span class="line"><span>acceptable-ranges = 1#range-unit / &quot;none&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><strong>响应</strong>字段，声明服务端是否支持范围请求：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Accept-Ranges: bytes</span></span>
<span class="line"><span>Accept-Ranges: none</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>唯一标准单位是 <strong><code>bytes</code></strong>。<code>none</code> 表示明确不支持。字段缺失时客户端<strong>不应假定</strong>支持，但可以试探性发送 <code>Range</code>。</p><h2 id="range" tabindex="-1">Range <a class="header-anchor" href="#range" aria-label="Permalink to &quot;Range&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Range            = ranges-specifier</span></span>
<span class="line"><span>ranges-specifier = range-unit &quot;=&quot; range-set</span></span>
<span class="line"><span>range-set        = 1#range-spec</span></span>
<span class="line"><span>range-spec       = int-range / suffix-range / other-range</span></span>
<span class="line"><span>int-range        = first-pos &quot;-&quot; [ last-pos ]</span></span>
<span class="line"><span>suffix-range     = &quot;-&quot; suffix-length</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h3 id="三种形式" tabindex="-1">三种形式 <a class="header-anchor" href="#三种形式" aria-label="Permalink to &quot;三种形式&quot;">​</a></h3><p>设表示总长为 10000 字节：</p><table tabindex="0"><thead><tr><th>写法</th><th>含义</th><th>实际字节</th></tr></thead><tbody><tr><td><code>bytes=0-499</code></td><td>第 0 到第 499 字节</td><td>前 500 字节</td></tr><tr><td><code>bytes=500-</code></td><td>从第 500 字节到末尾</td><td>后 9500 字节</td></tr><tr><td><code>bytes=-500</code></td><td><strong>最后</strong> 500 字节</td><td>第 9500–9999 字节</td></tr></tbody></table><p><strong>两端均为闭区间</strong>——<code>bytes=0-499</code> 是 500 字节，不是 499。这是最高频的差一错误。</p><p><code>bytes=-500</code> 的前导 <code>-</code> <strong>不是负数</strong>，是「后缀长度」记法。</p><h3 id="多范围" tabindex="-1">多范围 <a class="header-anchor" href="#多范围" aria-label="Permalink to &quot;多范围&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Range: bytes=0-499, 1000-1499, -200</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li>范围<strong>可以</strong>重叠、<strong>可以</strong>乱序。</li><li>服务端 <strong>MAY</strong> 合并重叠范围、<strong>MAY</strong> 按升序重排、<strong>MAY</strong> 只返回其中一部分。</li><li>服务端 <strong>MAY</strong> 因范围过多（DoS 防护）直接返回 <code>200</code> 完整内容——这是允许的降级。</li></ul><h3 id="服务端处理规则" tabindex="-1">服务端处理规则 <a class="header-anchor" href="#服务端处理规则" aria-label="Permalink to &quot;服务端处理规则&quot;">​</a></h3><ul><li><code>Range</code> <strong>仅对 <code>GET</code> 有定义</strong>；其他方法收到时 <strong>MUST</strong> 忽略。</li><li><code>first-pos</code> &gt; <code>last-pos</code> → 该 range-spec <strong>非法</strong>，整个 <code>Range</code> 字段 <strong>MUST</strong> 被忽略（按 <code>200</code> 处理）。</li><li>所有范围都超出表示长度 → <strong>416 Range Not Satisfiable</strong>。</li><li>部分范围可满足 → 只返回可满足的那些，<code>206</code>。</li><li><code>last-pos</code> 超出末尾 → 截断到末尾，不算错误。</li><li>服务端<strong>始终</strong>可以忽略 <code>Range</code> 返回完整 <code>200</code>。</li></ul><h2 id="content-range" tabindex="-1">Content-Range <a class="header-anchor" href="#content-range" aria-label="Permalink to &quot;Content-Range&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Content-Range     = range-unit SP ( range-resp / unsatisfied-range )</span></span>
<span class="line"><span>range-resp        = incl-range &quot;/&quot; ( complete-length / &quot;*&quot; )</span></span>
<span class="line"><span>incl-range        = first-pos &quot;-&quot; last-pos</span></span>
<span class="line"><span>unsatisfied-range = &quot;*/&quot; complete-length</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>三种形态：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Content-Range: bytes 0-499/10000      表示总长已知</span></span>
<span class="line"><span>Content-Range: bytes 0-499/*          总长未知（流式生成）</span></span>
<span class="line"><span>Content-Range: bytes */10000          416 响应，告知实际总长</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>要点：</p><ul><li>单位与范围之间是 <strong>SP</strong>，不是 <code>=</code>（与 <code>Range</code> 相反）——高频写错点。</li><li><code>complete-length</code> 是<strong>完整表示</strong>的长度，不是本次返回的长度；本次长度由 <code>Content-Length</code> 给出。</li><li><code>Content-Range</code> 在 <strong><code>PUT</code> 请求中无意义</strong>，服务端收到 <strong>MUST</strong> 返回 <code>400</code>。</li></ul><h2 id="_206-的构造" tabindex="-1">206 的构造 <a class="header-anchor" href="#_206-的构造" aria-label="Permalink to &quot;206 的构造&quot;">​</a></h2><h3 id="单范围" tabindex="-1">单范围 <a class="header-anchor" href="#单范围" aria-label="Permalink to &quot;单范围&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HTTP/1.1 206 Partial Content</span></span>
<span class="line"><span>Content-Range: bytes 0-499/10000</span></span>
<span class="line"><span>Content-Length: 500</span></span>
<span class="line"><span>Content-Type: text/html</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&lt;500 字节数据&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><ul><li><strong>MUST</strong> 带 <code>Content-Range</code>。</li><li><code>Content-Length</code> = 本次返回的字节数（500），不是 10000。</li></ul><h3 id="多范围-multipart-byteranges" tabindex="-1">多范围：multipart/byteranges <a class="header-anchor" href="#多范围-multipart-byteranges" aria-label="Permalink to &quot;多范围：multipart/byteranges&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HTTP/1.1 206 Partial Content</span></span>
<span class="line"><span>Content-Type: multipart/byteranges; boundary=SEP</span></span>
<span class="line"><span></span></span>
<span class="line"><span>--SEP</span></span>
<span class="line"><span>Content-Type: text/html</span></span>
<span class="line"><span>Content-Range: bytes 0-499/10000</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&lt;数据&gt;</span></span>
<span class="line"><span>--SEP</span></span>
<span class="line"><span>Content-Type: text/html</span></span>
<span class="line"><span>Content-Range: bytes 1000-1499/10000</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&lt;数据&gt;</span></span>
<span class="line"><span>--SEP--</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br></div></div><p>规则：</p><ul><li><strong>不带</strong>顶层 <code>Content-Range</code>——每个 part 各自带。</li><li>每个 part <strong>MUST</strong> 带 <code>Content-Range</code>，<strong>SHOULD</strong> 带 <code>Content-Type</code>。</li><li>即使只请求了一个范围，服务端也<strong>可以</strong>用 multipart 形式回应；客户端必须能处理两种形态。</li></ul><h3 id="_206-中的其他字段" tabindex="-1">206 中的其他字段 <a class="header-anchor" href="#_206-中的其他字段" aria-label="Permalink to &quot;206 中的其他字段&quot;">​</a></h3><p><code>206</code> <strong>MUST</strong> 包含若返回 <code>200</code> 时会发的这些字段：<code>Date</code>、<code>Cache-Control</code>、<code>ETag</code>、<code>Content-Location</code>、<code>Expires</code>、<code>Vary</code>。</p><h2 id="if-range" tabindex="-1">If-Range <a class="header-anchor" href="#if-range" aria-label="Permalink to &quot;If-Range&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>If-Range = entity-tag / HTTP-date</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>解决<strong>断点续传时资源已变</strong>的问题。客户端把上次拿到的验证器带上：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /big.iso HTTP/1.1</span></span>
<span class="line"><span>Range: bytes=5000000-</span></span>
<span class="line"><span>If-Range: &quot;abc123&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>服务端处理：</p><ul><li>验证器<strong>匹配</strong> → 资源未变，返回 <code>206</code> 续传部分。</li><li>验证器<strong>不匹配</strong> → 资源已变，<strong>忽略 <code>Range</code></strong>，返回完整 <code>200</code>（而不是 <code>412</code>）。</li></ul><p>关键约束：</p><ul><li><strong>必须用强验证器</strong>。用 <code>ETag</code> 时是<strong>强比较</strong>；弱 ETag 不可用于 <code>If-Range</code>。</li><li>用日期形式时，仅当服务端能确保该 <code>Last-Modified</code> 是强验证器（与 <code>Date</code> 差 ≥1 秒）才可信任。</li><li><code>If-Range</code> <strong>无 <code>Range</code> 时必须被忽略</strong>。</li><li>该设计让客户端一次往返就能处理两种情况：要么续传，要么重下。</li></ul><h2 id="缓存与范围" tabindex="-1">缓存与范围 <a class="header-anchor" href="#缓存与范围" aria-label="Permalink to &quot;缓存与范围&quot;">​</a></h2><ul><li>缓存可以存储 <code>206</code> 的部分内容，并在后续范围请求时<strong>拼接</strong>已存片段——前提是各片段的<strong>验证器相同</strong>。</li><li>验证器不同的片段<strong>MUST NOT</strong> 拼接（会产生损坏文件）。</li><li>这正是弱 ETag 被禁止用于 <code>Range</code> 的根本原因。</li></ul><p>下一篇：<a href="/Front2Full/manual/computer-programming/http11/caching">缓存</a>——Cache-Control 指令全集与新鲜度计算。</p>`,45)])])}const b=a(p,[["render",l]]);export{u as __pageData,b as default};
